import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Changelog Notes","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/changelog.md","filePath":"en/guide/changelog.md","lastUpdated":0}`),a={name:`en/guide/changelog.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="changelog-notes" tabindex="-1">Changelog Notes <a class="header-anchor" href="#changelog-notes" aria-label="Permalink to “Changelog Notes”">​</a></h1><p>This page explains the current documentation sync focus and provides an upgrade checklist. For complete release information, also check the per-module <code>CHANGELOG.md</code> files, default configuration files, and the release package you are using. 13 of the 14 runtime modules ship a <code>CHANGELOG.md</code>; <strong>EmakiMobs does not have one yet</strong>, so use its default <code>config.yml</code> and release notes for version changes instead.</p><h2 id="legacy-configured-item-automatic-migration-has-been-retired" tabindex="-1">Legacy configured-item automatic migration has been retired <a class="header-anchor" href="#legacy-configured-item-automatic-migration-has-been-retired" aria-label="Permalink to “Legacy configured-item automatic migration has been retired”">​</a></h2><ul><li>The runtime <strong>no longer migrates</strong> legacy item fields automatically: CoreLib shared GUI files and EmakiItem <code>items/</code> definitions should use the canonical <code>item.source</code>, <code>item.amount</code>, and <code>item.components</code> directly.</li><li>Historical fields such as <code>material</code>, <code>display_name</code>, <code>lore</code>, model data, and enchantments are not rewritten or filled in; legacy forms are no longer silently patched or upgraded automatically.</li><li>Legacy forms in the other modules can still be handled with each module&#39;s one-shot command (confirm in preview mode first, then add <code>confirm</code> to apply): <code>/emakiforge convert-legacy</code>, <code>/emakigem convert-legacy</code>, <code>/emakistrengthen convert-legacy</code>, <code>/emakilevel convert-legacy</code>, <code>/emakicooking convert-legacy</code>. The converters are migration utilities rather than plugin features; see the <a href="./../modules/corelib/legacy-converter-retirement.html">legacy config converter retirement list</a> for the full retirement list.</li><li>For production upgrades, back up the full configuration directory first.</li></ul><h2 id="corelib-boundary-change-domain-protocols-moved-back-to-business-modules" tabindex="-1">CoreLib boundary change: domain protocols moved back to business modules <a class="header-anchor" href="#corelib-boundary-change-domain-protocols-moved-back-to-business-modules" aria-label="Permalink to “CoreLib boundary change: domain protocols moved back to business modules”">​</a></h2><p>CoreLib no longer owns domain protocols and extension points. Use the current owners:</p><ul><li>The item layer preview SPI (<code>ItemLayerPreviewProvider</code>, <code>ItemLayerPreviewRequest</code>, and related types) was removed from CoreLib and is now owned by <code>EmakiItemApi</code> in <code>emaki.jiuwu.craft.item.api.preview</code>.</li><li>Equipment skill PDC keys and their codec are now owned solely by <code>emaki.jiuwu.craft.skills.api.pdc.EquipmentSkillPdcCodec</code> in <code>EmakiSkillsApi</code>.</li><li>The attribute PDC and attribute service contract is now authoritative in <code>EmakiAttributeApi</code> (<code>emaki.jiuwu.craft.attribute.api.PdcAttributeAccess</code> with the full <code>PdcAttributePayload</code>), reached through <code>EmakiAttributeApi.extensions().pdc()</code>.</li><li>All CoreLib compatibility adapters were removed in CoreLib <code>4.6.7</code>: <code>SkillPdcGateway</code>, <code>PdcAttributeGateway</code>, and the mirror types <code>PdcAttributeApi</code>, <code>PdcAttributePayloadSnapshot</code>, and <code>EmakiAttributeBridge</code> no longer exist. External code still referencing them will throw <code>NoClassDefFoundError</code>.</li></ul><h2 id="documentation-update-highlights-2026-09-18" tabindex="-1">Documentation update highlights (2026-09-18) <a class="header-anchor" href="#documentation-update-highlights-2026-09-18" aria-label="Permalink to “Documentation update highlights (2026-09-18)”">​</a></h2><p>This round re-verified the documentation against the current source, POMs, default resources, and descriptors. The main changes are:</p><ul><li><strong>Version line sync</strong>: module versions, Jar file names, Maven/Gradle coordinates, and <code>config.yml</code> / <code>lang/*.yml</code> resource versions for all 14 runtime/API modules are aligned with the current POMs; the module version tables in the README and the documentation site were updated as well.</li><li><strong>Repository structure</strong>: the default reactor has 23 modules (14 API + 9 runtime); the <code>private-modules</code> profile adds 5 more runtime modules (Skills, Gem, Item, Storage, Accessory), for 28 in total when enabled. Module counts and profile membership in the README and the getting-started pages were corrected against <code>pom.xml</code>.</li><li><strong>CoreLib numeric actions</strong>: added the <code>take_food</code> section; the health, food, experience, currency, and item-count sections now validate explicitly (negative and non-finite values return <code>INVALID_CONFIG</code> instead of being silently clamped); an insufficient deduction returns <code>REJECTED</code> with no partial deduction; added documentation for the <code>action.audit</code> audit log.</li><li><strong>CoreLib animation</strong>: documented the <code>api.animation</code> contract and the <code>registerAnimation</code> / <code>playAnimationAsync</code> / <code>stopAnimation</code> / <code>addAnimationListener</code> facades; corrected the incorrect statement that animation definitions need to be replayed after a CoreLib reload — the animation registry survives reloads, and it is the action section table that needs callbacks rebuilt; K-frame examples now use valid pipeline syntax.</li><li><strong>Item source aliases</strong>: added <code>mc</code> to the VANILLA aliases; removed the invalid <code>eco</code> alias under ECOITEMS.</li><li><strong>EmakiMobs</strong>: <code>skills</code> / <code>attributes</code> changed to the current <code>actions</code> / <code>ea_attributes</code> keys (legacy keys fall back with a WARN); added the <code>list</code> / <code>info</code> / <code>kill</code> / <code>count</code> / <code>debug</code> commands and permissions; the public API adds <code>identify</code>, <code>refresh</code>, and the three-argument <code>registerCustomSpawner</code> signature; <code>model.api</code> and <code>model.lod</code> are marked &quot;parsed but not currently effective&quot;, and LOD now has near/far tiers; model and action examples use valid pipeline syntax; <code>drain_timeout_seconds</code> is marked as a compatibility-retained entry.</li><li><strong>EmakiAttribute</strong>: documented that <code>&amp;</code> color codes in MythicMobs names are converted to MiniMessage.</li><li><strong>EmakiAccessory</strong>: added the player data file structure (<code>pages.&lt;page&gt;.&lt;slot&gt;</code>) plus v1→v2 automatic upgrade and the refusal to persist unrecognized structures; corrected the skill payload codec class name.</li><li><strong>Configuration keys and permissions</strong>: Level drops the non-existent <code>storage</code> section and <code>pdc.sync_on_*</code>; Station decomposition recipes use <code>item_sources</code> (<code>input_source</code> is the legacy key), <code>tags</code> no longer participate in station binding, and invalid <code>weight</code> values fall back to 1.0; Skills adds <code>cast_mode.enabled</code> and <code>trigger_settings.legacy_dispatch_cancelled_events</code>; corrected the <code>help</code> command permissions for Skills / Storage; Gem removes non-existent placeholders and <code>gem_slot_presentation</code>, clarifies that the gem ID comes from the <code>id</code> field, and adds an <code>item_sources</code> criterion; Forge corrects the <code>material_id</code> fallback order.</li><li><strong>Retired content removed</strong>: the description of legacy configured-item automatic migration was replaced with the retirement notice (see the section above).</li></ul><h2 id="historical-sync-focus-kept-for-reference" tabindex="-1">Historical sync focus (kept for reference) <a class="header-anchor" href="#historical-sync-focus-kept-for-reference" aria-label="Permalink to “Historical sync focus (kept for reference)”">​</a></h2><p>The following content is from earlier documentation sync rounds and is kept for traceability; parts corrected by this round or already retired are superseded by the sections above and each module page.</p><h3 id="runtime-boundary-and-configuration-sync-focus" tabindex="-1">Runtime boundary and configuration sync focus <a class="header-anchor" href="#runtime-boundary-and-configuration-sync-focus" aria-label="Permalink to “Runtime boundary and configuration sync focus”">​</a></h3><ul><li><strong>Platform and scheduling</strong><ul><li><code>paper-plugin.yml</code> descriptors now declare Paper 1.21.8+ and Folia support. CoreLib provides the Folia scheduler adapter, and business modules route delayed tasks, async work, GUI return-to-main-thread refreshes, and display refreshes through unified scheduling entry points.</li><li>Requirements now target Paper 1.21.8+ and include the current Folia support declaration.</li></ul></li><li><strong>GUI and item presentation</strong><ul><li>GUI slots use <code>item</code> as the current structured item-source field. Dynamic information, confirmation, and preview slots prefer template <code>item</code>, <code>display_name</code>, <code>lore</code>, and component settings.</li><li>EmakiGem inlay/open/upgrade GUIs no longer auto-fill the target item from the player&#39;s main hand or inventory when opened. Players must place target equipment and materials manually.</li><li>EmakiSkills skill panels, trigger selection, and EmakiStrengthen preview/confirmation dynamic slots now follow the same template-first GUI rule.</li></ul></li><li><strong>Attributes and PDC</strong><ul><li>Attribute supports ranged random values. Lore/PDC parsing can represent percentage and integer ranges, and snapshots keep minimum, maximum, and resolved values for ranged contributions.</li><li><code>variables</code> and <code>ea_attributes</code> are separated more strictly: variables are text/placeholder context, while real attribute output should use explicit <code>ea_attributes</code>.</li><li>Recent cleanup removed <code>ea_attribute_meta</code> logic; materials, gems, items, and strengthen configs should not rely on it as the current attribute metadata entry.</li></ul></li><li><strong>Cooking recipes</strong><ul><li>Recipe results now use the unified <code>result.&lt;branch&gt;.outputs/actions</code> structure. Success, early, over, undercooked, overcooked, and invalid branches follow the same model.</li><li>Recipe completion conditions were added, and station interaction keys were adjusted to the current source behavior.</li><li>Station floating text, display backend, and refresh configuration are part of the current configuration line.</li></ul></li><li><strong>Level</strong><ul><li>Added the EmakiLevel / EmakiLevelApi module for multiple level types, exp sources, requirements, PDC, PlaceholderAPI, CoreLib actions, MythicMobs drops, and EmakiAttribute contribution bridging.</li><li>VitePress now includes detailed Level module documentation, and the getting-started, introduction, and architecture pages include the progression module.</li></ul></li><li><strong>Forge / Gem / Strengthen / Item / Skills</strong><ul><li>Forge material effects show only payload fields for the selected effect type. <code>quality_modify</code> uses <code>tier</code>, and <code>capacity_bonus</code> uses <code>value</code>.</li><li>Gem items are refreshed from the current gem definition when obtained, after reloads, and when reconstructed inside GUIs.</li><li>Skills, Strengthen, Forge, Gem, and Item use the <code>es_skills</code> list form for skill effects in current examples and documentation.</li></ul></li></ul><h3 id="added-and-expanded" tabindex="-1">Added and expanded <a class="header-anchor" href="#added-and-expanded" aria-label="Permalink to “Added and expanded”">​</a></h3><ul><li><strong>Attribute</strong><ul><li>Configuration directory documentation for <code>config.yml</code>, <code>attribute_balance.yml</code>, <code>attributes/</code>, <code>damage_types/</code>, <code>conditions/</code>, and <code>lore_formats/</code>.</li><li>Scaling curve documentation for <code>logarithmic</code>, <code>sqrt</code>, and <code>piecewise_linear</code> rules.</li><li>Damage documentation now includes synthetic hit feedback when vanilla damage is intercepted.</li></ul></li><li><strong>Gem</strong><ul><li>Socket opener documentation for <code>socket_openers</code>, opener items, socket type filtering, and failure feedback.</li><li>Inlay success rate documentation for the current <code>inlay_success</code> structure.</li><li>Gem resonance documentation now covers <code>min_level</code>, <code>priority</code>, <code>exclusive_group</code>, and the actual <code>effects</code> object structure.</li></ul></li><li><strong>Skills</strong><ul><li>Action bar documentation for templates, update interval, and cast mode display.</li><li>Script engine limits, including per-phase action count and per-action target limits.</li><li>Passive trigger settings and <code>combo_attack</code> behavior.</li></ul></li><li><strong>Cooking</strong><ul><li>Command and permission documentation for <code>/ec debug</code>, oven, juicer, and fermentation barrel permissions.</li><li>Station documentation for display entities, display distance, refresh interval, wok animation, and scald damage.</li></ul></li><li><strong>Forge</strong><ul><li>Forge history documentation for audit records, auto-save, and troubleshooting.</li><li>Quality documentation keeps quality pools, guarantee counters, quality item metadata, and deterministic algorithm notes.</li></ul></li><li><strong>Strengthen</strong><ul><li>Branch tree documentation for branch recipe files and transfer design notes.</li></ul></li><li><strong>Item</strong><ul><li>Command documentation includes <code>/ei debug</code> and <code>emakiitem.debug</code>.</li></ul></li></ul><h3 id="removed-or-corrected" tabindex="-1">Removed or corrected <a class="header-anchor" href="#removed-or-corrected" aria-label="Permalink to “Removed or corrected”">​</a></h3><ul><li><strong>Gem commands</strong><ul><li>Removed old admin entries that are not in the current command router.</li><li>Current command set: <code>/emakigem gui &lt;inlay|open|upgrade&gt;</code>, <code>reload</code>, <code>inspect</code>, <code>clearstate</code>, and <code>debug</code>.</li><li>Current permissions: <code>emakigem.use</code>, <code>emakigem.reload</code>, <code>emakigem.admin</code>, and <code>emakigem.debug</code>.</li></ul></li><li><strong>Skills commands</strong><ul><li>GUI entry is <code>/eskills gui</code>.</li><li>Old trigger management commands were removed.</li><li><code>/eskills clearslot &lt;player&gt; &lt;slot&gt;</code> is documented.</li><li><code>castmode</code> is documented as <code>/eskills castmode &lt;on|off|toggle&gt;</code>.</li></ul></li><li><strong>Cooking permissions</strong><ul><li>Juicer collect permission is <code>emakicooking.station.juicer.collect</code>.</li><li>Fermentation barrel start permission is <code>emakicooking.station.fermentation_barrel.start</code>.</li><li>Station permissions use the <code>emakicooking.station.*</code> form.</li></ul></li></ul><h2 id="module-version-lines" tabindex="-1">Module version lines <a class="header-anchor" href="#module-version-lines" aria-label="Permalink to “Module version lines”">​</a></h2><p>The current source tree does not use one single version number for every module. Prefer each module&#39;s <code>src/main/resources/config.yml</code> and <code>pom.xml</code> when upgrading:</p><table tabindex="0"><thead><tr><th>Module</th><th>Current default config version</th></tr></thead><tbody><tr><td>EmakiCoreLib</td><td><code>4.8.8</code></td></tr><tr><td>EmakiAttribute</td><td><code>4.8.1</code></td></tr><tr><td>EmakiForge</td><td><code>4.8.1</code></td></tr><tr><td>EmakiStrengthen</td><td><code>4.8.2</code></td></tr><tr><td>EmakiCooking</td><td><code>4.3.1</code></td></tr><tr><td>EmakiLevel</td><td><code>1.6.1</code></td></tr><tr><td>EmakiCodex</td><td><code>1.1.0</code></td></tr><tr><td>EmakiStation</td><td><code>1.1.3</code></td></tr><tr><td>EmakiGem</td><td><code>2.8.2</code></td></tr><tr><td>EmakiSkills</td><td><code>2.8.1</code></td></tr><tr><td>EmakiItem</td><td><code>2.8.1</code></td></tr><tr><td>EmakiStorage</td><td><code>1.1.0</code></td></tr><tr><td>EmakiAccessory</td><td><code>1.1.2</code></td></tr><tr><td>EmakiMobs</td><td><code>1.0.3</code></td></tr></tbody></table><p>All 14 modules currently ship a <code>config.yml</code> and <code>lang/*.yml</code> version identical to their own <code>pom.xml</code>, so this table doubles as the module release-version table. A few modules keep an internal migration constant (<code>AppConfig.CURRENT_VERSION</code>) on a separate track; do not mix the two: Codex is <code>1.0.14</code>, Cooking is <code>3.3.14</code>, Forge is <code>4.5.11</code>, Gem is <code>2.7.8</code>, Mobs is <code>1.0.0</code>, Skills is <code>2.5.11</code>, Station is <code>1.0.2</code>, and Storage is <code>1.0.6</code>.</p><p>The equipment skill PDC contract has been merged into <code>emaki-skills-api</code>; there is no longer a separate <code>emaki-skills-protocol</code> artifact.</p><p>Different version lines reflect separate release cadence, not feature importance.</p><h2 id="recommended-reading-order" tabindex="-1">Recommended reading order <a class="header-anchor" href="#recommended-reading-order" aria-label="Permalink to “Recommended reading order”">​</a></h2><ol><li>Read the target module overview page to confirm responsibilities and dependencies.</li><li>Read commands and permissions before configuring permission groups.</li><li>Read configuration directory or core feature pages to understand default files.</li><li>Read feature-specific pages such as socket openers, skill triggers, attribute scaling, forge quality, or cooking stations.</li><li>After editing configuration, verify with the module&#39;s reload, inspect, debug, or lint command if available.</li><li>Before upgrading a live server, test with real equipment and player data on a staging server.</li></ol><h2 id="upgrade-checklist" tabindex="-1">Upgrade checklist <a class="header-anchor" href="#upgrade-checklist" aria-label="Permalink to “Upgrade checklist”">​</a></h2><ul><li>Back up all <code>plugins/Emaki*/</code> configuration directories.</li><li>Back up player data, equipment data, Cooking station data, Station queue data, Accessory data, and economy data.</li><li>Do not blindly overwrite old configuration files; compare defaults and merge new fields manually. The legacy configured-item automatic migration has been retired, legacy item definitions are not converted on startup, and they must be migrated by hand to the canonical <code>item.source</code> / <code>item.amount</code> / <code>item.components</code> structure.</li><li>Check whether commands and permission nodes match the current documentation.</li><li>Check whether Attribute <code>hard_lock_damage</code> and environmental damage mapping fit your server.</li><li>Check whether Gem has merged <code>socket_openers</code>, <code>inlay_success</code>, and global <code>upgrade</code> configuration.</li><li>Check whether Skills has merged <code>actionbar</code>, <code>script_engine</code>, and <code>passive_trigger_settings</code>.</li><li>Check whether Cooking has merged oven, juicer, fermentation barrel station settings, GUI files, and permissions.</li><li>Check whether Forge quality, history, and condition failure strategies match your gameplay.</li><li>Check whether Item auto-update and repair configuration affect old items.</li></ul><h2 id="troubleshooting-tips" tabindex="-1">Troubleshooting tips <a class="header-anchor" href="#troubleshooting-tips" aria-label="Permalink to “Troubleshooting tips”">​</a></h2><ul><li>When configuration fails to load, check the first YAML parse error in the console; the errors after it are usually cascading results.</li><li>When item attributes look wrong, first confirm whether the CoreLib assembly layer was rebuilt, then check the Attribute PDC output.</li><li>When a GUI cannot be operated, check permissions, slot configuration, template IDs, and item sources first.</li><li>When randomized features such as success rates, quality, or strengthen results behave oddly, check formula variables, guarantee counters, and failure handling strategies first.</li><li>For effects that span modules, troubleshoot in the order CoreLib → Attribute/Skills → business modules.</li></ul>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};